package ru.railbrake.calculator.core

/**
 * Предметные деревья для критичных карточек, которые в расширенном каталоге
 * начинались с универсального шаблона. Здесь уточняется наблюдение и граница
 * допуска, но не добавляются ремонтные операции или обходы защит.
 */
object DiagnosticDeepening {
    fun enrich(scenario: DiagnosticScenario): DiagnosticScenario = when (scenario.id) {
        "aux-common-loss" -> scenario.deepen(
            questions = listOf(
                q("aux-scope", "Остановились все вспомогательные машины или только одна группа?", "Общая причина питания или управления вероятнее локального отказа двигателя.", "Проверять цепь конкретной машины, её контактор и защиту.", "aux-phase"),
                q("aux-phase", "Фазорасщепитель работает и его состояние подтверждено?", "Разделять потерю общего питания и отказ отходящей цепи.", "Не считать отказы нескольких машин независимыми; проверить общую цепь собственных нужд.", "aux-cooling"),
                q("aux-cooling", "Потеряны охлаждение или запас сжатого воздуха?", "Снять связанную нагрузку и не допускать работы оборудования без охлаждения/воздуха.", "Зафиксировать состав отключившихся потребителей и последовательность события.", DiagnosticRepository.END_OF_FLOW)
            ),
            causes = listOf("Потеря питания цепей собственных нужд.", "Не запустился или отключился фазорасщепитель.", "Пропала общая команда либо напряжение цепей управления.", "Сработала защита группы вспомогательных машин.", "Отказ отдельного контактора или двигателя — если остальные потребители работают."),
            checks = listOf(
                cab("Состав отказа", "Сопоставить состояние фазорасщепителя, вентиляторов и компрессора по индикации и звуку.", "Определено, общий это отказ или локальный.", "При одновременной остановке не нагружать охлаждаемое оборудование."),
                cab("Связанные последствия", "Контролировать рост температуры и давление главных резервуаров.", "Охлаждение и запас воздуха достаточны для разрешённого режима.", "При снижении давления или потере охлаждения перейти к безопасной остановке."),
                authorized("Цепи собственных нужд", "Проверить питание, защиту и контакторы по схеме конкретной секции.", "Причина подтверждена измерением.", "Не шунтировать защиту и не удерживать контактор вручную.")
            ),
            related = listOf("phase-splitter-no-start", "motor-fan-failure", "compressor-no-start", "control-voltage-low")
        )

        "fan-low-airflow" -> scenario.deepen(
            questions = listOf(
                q("flow-motor", "Слышна работа двигателя вентилятора?", "Отделить вращение двигателя от фактического воздушного потока.", "Проверять питание, контактор и общую работу фазорасщепителя.", "flow-group"),
                q("flow-group", "Слабый поток только у одной охлаждаемой группы?", "Вероятны местная заслонка, воздуховод, направление вращения или механическая проблема вентилятора.", "Проверять общую производительность и питание группы вентиляторов.", "flow-heat"),
                q("flow-heat", "Есть рост температуры, запах или действие защиты охлаждаемого оборудования?", "Нагрузку снять; продолжать работу без подтверждённого охлаждения нельзя.", "Зафиксировать поток и режим, не имитируя нагрев для повторной проверки.", DiagnosticRepository.END_OF_FLOW)
            ),
            causes = listOf("Вентилятор не вращается при наличии команды.", "Повреждён или перекрыт воздуховод/заслонка.", "Недостаточная частота или неправильное направление вращения.", "Механическое повреждение рабочего колеса.", "Ошибка оценки потока либо отличие исполнения воздуховодов."),
            checks = listOf(
                cab("Команда и звук", "Сопоставить команду, индикацию, звук двигателя и изменение потока.", "Работа двигателя и поток согласованы.", "Не считать один звук двигателя доказательством охлаждения."),
                stop("Доступный внешний осмотр", "После безопасной остановки оценить доступные воздухозаборники и выходы без вскрытия ВВК.", "Нет засорения, касания, дыма или разрушения.", "При касании, запахе или нагреве машину не включать повторно."),
                authorized("Вентилятор и воздуховод", "Проверить привод, направление вращения, заслонки и тракт по документации исполнения.", "Расход воздуха восстановлен и подтверждён.", "Не эксплуатировать охлаждаемую группу без установленной нормы потока.")
            ),
            related = listOf("motor-fan-failure", "phase-splitter-no-start", "rectifier-overheat", "traction-motor-overheat")
        )

        "compressor-long-run" -> scenario.deepen(
            questions = listOf(
                q("long-pressure", "Давление главных резервуаров при работе компрессора растёт?", "Разделить недостаточную производительность и расход воздуха.", "Вероятны отсутствие подачи, механический отказ или крупная утечка.", "long-leak"),
                q("long-leak", "После остановки компрессора давление заметно падает без ожидаемого расхода?", "Искать утечку по доступным признакам и локализовать систему.", "Проверять регулятор давления и фактическую верхнюю границу отключения.", "long-cutoff"),
                q("long-cutoff", "Компрессор продолжает работать после достижения обычной верхней границы?", "Вероятна цепь регулятора/контактора; не допускать перегрева.", "Длительная работа связана с производительностью или расходом воздуха.", DiagnosticRepository.END_OF_FLOW)
