                stop("Доступная локализация утечки", "После закрепления выполнить установленный осмотр рукавов, кранов и слышимых утечек.", "Пневматический путь собран, крупной утечки нет.", "Не разъединять магистрали без закрепления и установленной подготовки."),
                authorized("КМ и связанная аппаратура", "Проверить КМ №395, ЭПК и разводку по пневматической схеме.", "Причина подтверждена и тормоза испытаны установленным порядком.", "Не признавать тормоза исправными только по одному манометру.")
            ),
            related = listOf("brake-pipe-leak", "compressor-no-start", "main-reservoir-leak", "equalizing-reservoir-mismatch")
        )

        "equalizing-reservoir-mismatch" -> scenario.deepen(
            questions = listOf(
                q("ur-move", "УР изменяется при переводе ручки КМ №395?", "Команда формируется; оценить, повторяет ли её ТМ.", "Вероятна проблема управляющей части КМ, линии УР или показания прибора.", "ur-tm"),
                q("ur-tm", "ТМ следует за изменением УР с ожидаемым характером?", "Проверить, не является ли расхождение только показанием одного манометра.", "Вероятны КМ №395, реле/клапаны по схеме или большой расход ТМ.", "ur-gauge"),
                q("ur-gauge", "Есть независимый признак фактического изменения тормозов, противоречащий приборам?", "Считать показания недостоверными и действовать по правилам отказа приборов/тормозов.", "Не делать вывод о неисправности только по небольшой динамической разнице.", DiagnosticRepository.END_OF_FLOW)
            ),
            causes = listOf("Неисправность либо засорение управляющей части КМ №395.", "Утечка или нарушение линии уравнительного резервуара.", "Большой расход/утечка тормозной магистрали.", "Недостоверный манометр УР или ТМ.", "Нормальная динамическая задержка ошибочно принята за отказ."),
            checks = listOf(
