                q("ib-tc", "При команде КВТ растёт давление хотя бы в одной группе ТЦ?", "Локализовать секцию/тележку и ветвь распределения.", "Проверять КВТ №254, РД №304 и общую командную линию.", "ib-effect"),
                q("ib-effect", "Давление ТЦ растёт, но тормозного эффекта нет?", "Вероятна механическая передача; движение до оценки безопасности не начинать.", "Отказ остаётся в пневматическом управлении или показании приборов.", DiagnosticRepository.END_OF_FLOW)
            ),
            causes = listOf("Нет достаточного питательного давления.", "КВТ №254 не формирует команду.", "РД №304 или связанная пневматическая ветвь не передаёт давление.", "Утечка либо закрытый путь к ТЦ.", "Повреждена тормозная рычажная передача.", "Недостоверно показание ТЦ."),
