                q("ir-scope", "Не отпускает только одна тележка или секция?", "Вероятна локальная пневматическая/механическая причина.", "Вероятна общая команда, КВТ либо повторительное действие по схеме.", "ir-heat"),
                q("ir-heat", "Есть нагрев, запах, дым или следы юза?", "Остановиться и исключить дальнейшее движение до установленного решения.", "После закрепления выполнить разрешённый осмотр и зафиксировать остаточное давление.", DiagnosticRepository.END_OF_FLOW)
            ),
            causes = listOf("КВТ №254 не обеспечивает отпуск.", "РД №304 или выпускной путь не снижает давление.", "Зажата/повреждена пневматическая линия.", "Заклинила рычажная передача или колодка.", "Не отпущен ручной тормоз.", "Манометр показывает остаточное давление ошибочно."),
            checks = listOf(
                cab("Давление после отпуска", "Записать давление ТЦ по секциям и его изменение после команды отпуска.", "ТЦ снижается, тормозной эффект исчезает.", "Не начинать движение при сохраняющемся давлении или эффекте."),
                stop("Тележка и колодки", "После закрепления осмотреть колодки, ручной тормоз и доступную рычажную передачу.", "Колодки отошли, нагрева и заклинивания нет.", "Не касаться нагретых деталей и не освобождать механизм под нагрузкой."),
                authorized("Выпускная ветвь", "Проверить КВТ, РД, клапаны и трубопроводы по схеме.", "Причина подтверждена, выполнено полное испытание.", "Не выпускать воздух разъединением случайной магистрали.")
            ),
            related = listOf("wheel-dragging", "brake-rigging-damage", "handbrake-not-release", "brake-cylinder-imbalance")
        )

        "brake-cylinder-imbalance" -> scenario.deepen(
