                q("bi-mode", "Неравномерность появляется и при автоматическом, и при независимом торможении?", "Общая для ТЦ/механики причина вероятнее одного органа управления.", "Разделять автоматическую и независимую управляющие ветви.", "bi-release"),
                q("bi-release", "После отпуска одна группа ТЦ сохраняет давление или колодки не отходят?", "Риск нагрева и юза: движение до оценки безопасности не начинать.", "Проверять недостаточное наполнение, утечку или механический дефект другой группы.", DiagnosticRepository.END_OF_FLOW)
            ),
            causes = listOf("Утечка или сопротивление отдельной ветви ТЦ.", "Неодинаковая работа РД/клапанов по секциям.", "Недостоверное показание манометра.", "Перекос или повреждение рычажной передачи.", "Неотход колодок или ручного тормоза.", "Различие управляющих ветвей автоматического и независимого торможения."),
            checks = listOf(
                cab("Секции и режимы", "Записать давление ТЦ по секциям при одинаковой штатной команде и после отпуска.", "Наполнение и отпуск согласованы.", "При устойчивой разнице тормоза считать непроверенными."),
                stop("Сравнительный осмотр", "После закрепления сравнить положение колодок и доступной рычажной передачи тележек.", "Нет перекоса, неотхода, утечки и нагрева.", "При механическом повреждении дальнейшее движение — только по установленному решению."),
                authorized("Пневматические ветви", "Проверить давления непосредственно в предусмотренных контрольных точках и аппаратуру по схеме.", "Причина различия установлена, испытание успешно.", "Не уравнивать действие произвольной регулировкой без измерений.")
            ),
            related = listOf("brakes-no-apply-release", "independent-brake-no-apply", "independent-brake-no-release", "brake-rigging-damage")
        )

        else -> scenario
